import{_ as t}from"./chunks/icon.DxQwhVtI.js";import{_ as n,a,b as i}from"./chunks/cards-177.DbNRxSpU.js";import{_ as r,o as s,c as o,a3 as d}from"./chunks/framework.BlfGB29P.js";const A=JSON.parse('{"title":"Automation Status Card","description":"Automatische Automationsliste, Auswahl per Checkbox, Laufstatus und Trace-Diagnose. Version 0.1.3, DE/EN/FR.","frontmatter":{"title":"Automation Status Card","description":"Automatische Automationsliste, Auswahl per Checkbox, Laufstatus und Trace-Diagnose. Version 0.1.3, DE/EN/FR."},"headers":[],"relativePath":"projects/automation-status-card/index.md","filePath":"projects/automation-status-card/index.md","lastUpdated":1794134439000}'),l={name:"projects/automation-status-card/index.md"};function u(c,e,h,g,b,m){return s(),o("div",null,[...e[0]||(e[0]=[d('<h1 id="automation-status-card" tabindex="-1">Automation Status Card <a class="header-anchor" href="#automation-status-card" aria-label="Permalink to &quot;Automation Status Card&quot;">​</a></h1><p><strong>HA 2026.11.0, 05.11.2026, .177:</strong> Version 0.1.3 besteht Rendern, Ein/Aus mit Zustandsbestätigung, Laufanzeige, Trace-Abfrage, normalen Abschluss, Checkboxen, Alle auswählen/abwählen und Neuladen. Bubble-/Mushroom-Einzelvorlagen werden dargestellt. Eigene Testobjekte sind bereinigt. Fehlerfälle und Laufzeitwarnung wurden in dieser Version von HA nicht erneut gezielt provoziert; frühere Prüfergebnisse bleiben separat erhalten.</p><p><a href="/sammlung/ha-2026-11-kompatibilitaet">Prüfumfang, Ergebnisse und offene Punkte</a>.</p><img src="'+t+`" width="80" height="80" alt="Automation Status Card"><p><strong>0.1.3 · DE / EN / FR · MIT</strong></p><p><a href="https://github.com/rockbaer2007/automation-status-card" target="_blank" rel="noreferrer">GitHub</a> · <a href="https://github.com/rockbaer2007/automation-status-card/releases/tag/v0.1.3" target="_blank" rel="noreferrer">Download 0.1.3</a> · <a href="https://opensource.ugso-software.de/projects/automation-status-card/" target="_blank" rel="noreferrer">Open-Source-Doku</a></p><p>Listet automatisch alle für den angemeldeten HA-Benutzer verfügbaren <code>automation.*</code>-Entitäten alphabetisch auf. Standardmäßig sind acht Zeilen sichtbar; weitere Einträge werden vertikal gescrollt. Neue und entfernte Automationen werden automatisch berücksichtigt. Die Karte benötigt keine zusätzliche Kartenbibliothek.</p><p><a href="/en/projects/automation-status-card/">English</a> · <a href="/fr/projects/automation-status-card/">Français</a></p><p>Auf .177 mit HA 2026.10.4 geprüft: Grundversion 0.1.0 sowie Auswahl und Laufdiagnose in der korrigierten Fassung 0.1.3. Echte HA-Traces, Fehler, normaler Abschluss, Laufzeitwarnung, ausgeschaltete Warnung, Checkboxen und gespeicherte Auswahl erfolgreich geprüft. <a href="https://github.com/rockbaer2007/automation-status-card/blob/main/docs/TESTING.md" target="_blank" rel="noreferrer">Prüfbericht mit Bildern</a>.</p><h2 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h2><h3 id="hacs-marketplace" tabindex="-1">HACS / Marketplace <a class="header-anchor" href="#hacs-marketplace" aria-label="Permalink to &quot;HACS / Marketplace&quot;">​</a></h3><p><code>https://github.com/rockbaer2007/automation-status-card</code> als benutzerdefiniertes Repository in Kategorie <strong>Dashboard</strong> (<code>plugin</code>) hinzufügen und herunterladen. Kartenressource: <code>/hacsfiles/automation-status-card/automation-status-card.js</code>. Das Paket ist HACS-kompatibel, aber noch nicht in den Standardkatalog aufgenommen; ein eigener Marketplace-Installationstest wurde nicht durchgeführt. Keine Supervisor-App. HACS und manuelle Kopie nicht gleichzeitig laden.</p><h3 id="manuell" tabindex="-1">Manuell <a class="header-anchor" href="#manuell" aria-label="Permalink to &quot;Manuell&quot;">​</a></h3><ol><li>Vorher HA sichern. <code>dist/automation-status-card.js</code> bzw. die JS-Datei aus dem Paket nach <code>/config/www/automation-status-card/automation-status-card.js</code> kopieren.</li><li>Unter <strong>Einstellungen → Dashboards → Ressourcen</strong> als <strong>JavaScript-Modul</strong> hinzufügen: <code>/local/automation-status-card/automation-status-card.js</code>. Bestehende Ressourcen erhalten.</li><li>Dashboard neu laden und <strong>Automation Status Card</strong> im Kartenwähler auswählen oder die YAML-Konfiguration unten verwenden.</li></ol><p>Die Oberfläche folgt automatisch der HA-Sprache, unterstützt DE/EN/FR und verwendet ansonsten Englisch. Im visuellen Editor sind Titel, sichtbare Zeilen, Schalten und Sprache einstellbar.</p><p>Unter <strong>Automationen anzeigen</strong> sind zunächst alle Einträge angehakt: <strong>Haken = anzeigen</strong>, Haken entfernen = nur in dieser Karte ausblenden. <strong>Alle auswählen</strong> zeigt alle Einträge; <strong>Alle abwählen</strong> blendet alle derzeit aufgeführten Einträge aus. Neue Automationen erscheinen standardmäßig wieder ausgewählt. Die Auswahl wird je Karte gespeichert und verändert weder die Automation noch andere Karten. Vorübergehend nicht verfügbare, abgewählte Entitäten bleiben im Editor aufgeführt und können wieder angewählt werden.</p><p>Optional in YAML: <code>hidden_entities: [automation.meine_automation]</code>. Diese IDs sind abgewählt und werden ausgeblendet. Ohne diese Einstellung bleibt die bisherige Anzeige unverändert.</p><div class="language-yaml vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">type</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">custom:automation-status-card</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">title</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">Automationen</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">visible_rows</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">8</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">allow_toggle</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">language</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">auto</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><table tabindex="0"><thead><tr><th>Einstellung</th><th>Standard</th><th>Bedeutung</th></tr></thead><tbody><tr><td><code>title</code></td><td>Automationen, übersetzt</td><td>Überschrift; <code>&quot;&quot;</code> blendet sie aus.</td></tr><tr><td><code>visible_rows</code></td><td><code>8</code></td><td>Ganze Zahl von 1 bis 50; weitere Zeilen bleiben scrollbar.</td></tr><tr><td><code>allow_toggle</code></td><td><code>false</code></td><td>Nur Anzeige oder Schalter zum Aktivieren/Deaktivieren.</td></tr><tr><td><code>language</code></td><td><code>auto</code></td><td><code>auto</code>, <code>de</code>, <code>en</code>, <code>fr</code>.</td></tr><tr><td><code>show_health</code></td><td><code>true</code></td><td>Laufstatus und Diagnose anzeigen.</td></tr><tr><td><code>check_traces</code></td><td><code>true</code></td><td>Letzten beendeten Ablauf lesend prüfen; nur für HA-Administratoren.</td></tr><tr><td><code>runtime_warning_seconds</code></td><td><code>300</code></td><td>Laufzeitwarnung nach dieser Sekundenzahl; <code>0</code> schaltet nur die Warnung ab, höchstens 604800 (7 Tage).</td></tr></tbody></table><h2 id="laufstatus-und-fehlerhinweise" tabindex="-1">Laufstatus und Fehlerhinweise <a class="header-anchor" href="#laufstatus-und-fehlerhinweise" aria-label="Permalink to &quot;Laufstatus und Fehlerhinweise&quot;">​</a></h2><p>HA meldet manche Abbrüche nur als <code>aborted</code>, etwa eine nicht erfüllte Bedingung oder einen expliziten Fehlerstopp. Diese werden neutral als <strong>Letzter Ablauf abgebrochen – Grund in HA-Traces prüfen</strong> angezeigt. Die Karte erfindet dafür weder einen Erfolg noch einen Fehler.</p><p><strong>Ein/Aus bleibt die Aktivierung.</strong> Zusätzlich zeigt die Karte bei <code>current &gt; 0</code> <strong>Läuft</strong>, Anzahl der Durchläufe und die Laufzeit. Bei Überschreiten der konfigurierten Grenze erscheint <strong>Läuft ungewöhnlich lange</strong>. Das ist kein Absturznachweis: <code>delay</code>, Wartebedingungen und lange Aktionen können beabsichtigt sein. Es wird nichts automatisch beendet oder neu gestartet.</p><p>Bei passender vollständiger Trace-Liste verwendet die Karte den Beginn des ältesten laufenden Durchlaufs, begrenzt die Dauer aber immer auf die selbst beobachtete Zeit. So erzeugen abweichende HA-/Browser-Uhren keine verfrühte Warnung. Ansonsten zählt sie konservativ erst ab der Beobachtung, mit entsprechendem Zusatz. <code>last_triggered</code> allein wird nicht als Laufzeit verwendet. Bei einer neuen Auslösung nach der letzten Trace-Abfrage wird ebenfalls auf Beobachtungszeit zurückgefallen. Seitenwechsel, Neuladen und Verbindungsabbruch setzen die lokale Beobachtung zurück; dies ist kein Hintergrund-Watchdog.</p><p>Für Administratoren liest die Karte höchstens alle 30 Sekunden <code>trace/list</code> für Automationen, zusätzlich per <strong>Ablaufdaten aktualisieren</strong>. Nur Zusammenfassungen werden verarbeitet; keine vollständigen Traces, Variablen oder Automationskonfigurationen. Der jüngste beendete Ablauf wird als <strong>fehlerhaft</strong> markiert, wenn HA einen Fehler meldet. Ein normaler Stopp oder eine nicht erfüllte Bedingung gilt nicht automatisch als Fehler. Ein jüngerer beendeter Ablauf ohne gemeldeten Fehler löst den alten Fehlerhinweis ab. Zeitangaben stehen im Tooltip; die Detailansicht ist weiterhin über den Namen erreichbar.</p><p>Fehlende Administratorrechte, fehlende Automation-ID, keine gespeicherten Traces, eine nicht unterstützte Schnittstelle und Verbindungsfehler sind <strong>kein Automationsfehler</strong>. Die Karte zeigt fehlende Ablaufdaten entsprechend an. Bei getrennter HA-Verbindung wird kein veralteter Laufstatus als aktuell dargestellt. Trace-Abfragen funktionieren nur, soweit HA dem angemeldeten Benutzer Zugriff gibt; die Karte erweitert keine Rechte. Ein Fehler innerhalb einer mit <code>continue_on_error</code> fortgesetzten Aktion kann in der Zusammenfassung fehlen.</p><p>Grundlage: <a href="https://www.home-assistant.io/docs/automation/basics/" target="_blank" rel="noreferrer">HA-Automationsattribute</a>, <a href="https://github.com/home-assistant/core/blob/2026.10.4/homeassistant/components/trace/websocket_api.py" target="_blank" rel="noreferrer">Trace-WebSocket-API</a>, <a href="https://github.com/home-assistant/core/blob/2026.10.4/homeassistant/components/trace/models.py" target="_blank" rel="noreferrer">Trace-Zusammenfassungen</a>. Die HA-Schnittstelle kann sich in späteren Versionen ändern.</p><p>Ein/Aus bezeichnet <strong>aktiviert/deaktiviert</strong>, nicht „läuft gerade“. Die Karte startet keine Automation und verwendet keinen Trigger-Service. In der Liste öffnet der Name die HA-Detailansicht; bei erlaubtem Schalten aktiviert/deaktiviert der Schalter genau diese Automation. Beim Deaktivieren setzt die Karte <code>stop_actions: false</code>, damit ein bereits laufender Durchlauf nicht gezielt gestoppt wird. HA-Rechte gelten weiterhin; die Anzeigeoption ist keine Zugriffssperre.</p><p>Nicht verfügbare/unbekannte Automationen und getrennte Verbindungen lassen sich nicht schalten. Bis zur Zustandsbestätigung wird der jeweilige Schalter gesperrt. Fehler werden angezeigt; nach fehlender Bestätigung gibt es keinen automatischen Wiederholungsversuch. Maßgeblich bleibt der von HA gemeldete Zustand.</p><h2 id="einzelne-automation-mit-bubble-card-oder-mushroom" tabindex="-1">Einzelne Automation mit Bubble Card oder Mushroom <a class="header-anchor" href="#einzelne-automation-mit-bubble-card-oder-mushroom" aria-label="Permalink to &quot;Einzelne Automation mit Bubble Card oder Mushroom&quot;">​</a></h2><p>Im Ordner <code>examples</code> liegen vier unabhängige YAML-Vorlagen, jeweils für <strong>eine einzelne Automation</strong>:</p><ul><li><code>bubble-single-readonly.yaml</code> / <code>bubble-single-control.yaml</code></li><li><code>mushroom-single-readonly.yaml</code> / <code>mushroom-single-control.yaml</code></li></ul><p><code>automation.replace_me</code> durch die eigene Entität ersetzen. Die Anzeigevariante deaktiviert die Kartenaktionen, die Bedienvariante schaltet über die normale Toggle-Aktion der jeweiligen Erweiterung. Diese Vorlagen sind keine automatische Liste; sie laufen direkt als Bubble Card bzw. Mushroom Entity Card. Es ist kein zusätzlicher eigener Erweiterungscode nötig. Deren Standard-Aktionsverhalten gilt unabhängig von <code>allow_toggle</code> der Automation Status Card.</p><p>Die jeweiligen Erweiterungen müssen separat installiert sein. Ressourcenpfade unter Linux sind groß-/kleinschreibungssensitiv:</p><ul><li>Bubble Card: <code>/hacsfiles/Bubble-Card/bubble-card.js</code></li><li>Mushroom: <code>/hacsfiles/lovelace-mushroom/mushroom.js</code></li></ul><p>Die Vorlagen verändern keine bestehenden Karten. Fremde Erweiterungen werden nicht mitgeliefert. Quellen: <a href="https://github.com/Clooos/Bubble-Card" target="_blank" rel="noreferrer">Bubble Card</a>, <a href="https://github.com/piitaya/lovelace-mushroom" target="_blank" rel="noreferrer">Mushroom</a>.</p><h2 id="entwicklung" tabindex="-1">Entwicklung <a class="header-anchor" href="#entwicklung" aria-label="Permalink to &quot;Entwicklung&quot;">​</a></h2><p>Node 22 oder neuer: <code>npm ci</code>, <code>npm run check</code>, <code>npm run build</code>, <code>npm test</code>. Das Release enthält die gebaute JS-Datei separat und ein vollständiges ZIP mit Anleitungen und Beispielen. Nach einem manuellen Update den vorhandenen Ressourcenpfad beibehalten und <code>?v=0.1.3</code> ergänzen beziehungsweise aktualisieren, anschließend den Browser vollständig neu laden. <a href="https://github.com/rockbaer2007/automation-status-card/blob/main/docs/TESTING.md" target="_blank" rel="noreferrer">Testbericht</a>.</p><p>MIT-Lizenz. Keine externen Laufzeitdienste, keine eigenen Tokens und keine Telemetrie. Konfiguration wird durch HA im Dashboard gespeichert; vorhandene Automationsdefinitionen werden von der Karte nicht bearbeitet.</p><p><img src="`+n+'" alt="HA test: run warning and failure"></p><p><img src="'+a+'" alt="HA editor: selection"></p><p><img src="'+i+'" alt="Single-automation examples, initial-version test"></p>',41)])])}const w=r(l,[["render",u]]);export{A as __pageData,w as default};
